const items = $input.all().map(i => i.json);

// Scan + idat kayıtlarını sentrix_id / scan_ref bazında grupla
const groups = {};

for (const row of items) {
  const scanRef = String(row.scan_ref);
  const sentrixId = String(row.sentrix_id);

  const key = `${scanRef}__${sentrixId}`;

  if (!groups[key]) {
    groups[key] = {
      scan_ref: scanRef,
      sentrix_id: sentrixId,
      chiptype_ref: row.chiptype_ref,
      chip_config: row.chip_config,
      idats: [],
    };
  }

  groups[key].idats.push(row);
}

const output = [];

for (const group of Object.values(groups)) {
  const allIdats = group.idats;

  const toProcessIdats = allIdats.filter(x => {
    return x.gtc_file_path === null || x.gtc_file_path === undefined || x.gtc_file_path === '';
  });

  // Bu chip için işlenecek idat yoksa skip
  if (toProcessIdats.length === 0) {
    continue;
  }

  output.push({
    json: {
      status: 'process',
      sentrix_id: group.sentrix_id,
      scan_ref: group.scan_ref,
      chiptype_ref: group.chiptype_ref,
      chip_config: group.chip_config,

      total_idats: allIdats.length,
      to_process_count: toProcessIdats.length,

      // Kritik: sadece bu chip'in idatları
      process_idats: toProcessIdats,
      all_idats: allIdats,
    }
  });
}

if (output.length === 0) {
  return [{
    json: {
      status: 'nothing_to_process',
      message: 'GTC dosyası eksik olan idat bulunamadı'
    }
  }];
}

return output;

const inputItems = $input.all();
const output = [];

for (let index = 0; index < inputItems.length; index++) {
  const item = inputItems[index];

  const raw =
    item.json.stdout ??
    item.json.data ??
    item.json.output ??
    '';

  const lines = String(raw)
    .split('\n')
    .map(line => line.trim())
    .filter(Boolean);

  const jsonLine = [...lines]
    .reverse()
    .find(line => line.startsWith('{') && line.endsWith('}'));

  if (!jsonLine) {
    output.push({
      json: {
        status: 'parse_failed',
        message: 'SSH çıktısında JSON satırı bulunamadı',
        raw_stdout: raw,
      },
      pairedItem: { item: index },
    });
    continue;
  }

  try {
    const parsed = JSON.parse(jsonLine);

    output.push({
      json: parsed,
      pairedItem: { item: index },
    });
  } catch (error) {
    output.push({
      json: {
        status: 'json_parse_failed',
        message: error.message,
        raw_json_line: jsonLine,
      },
      pairedItem: { item: index },
    });
  }
}

return output;

const qcText = $('read_sentrix_qc_ssh').first().json.stdout || '';

const regByPos = {};
for (const line of qcText.split(/\r?\n/)) {
  const parts = line.trim().split(/\s+/);
  if (parts.length < 2) continue;
  const label = parts[0];
  if (!label.endsWith('_1_Swath1_Channel1')) continue;
  const pos = label.split('_')[0];
  const val = parseFloat(parts[1]);
  if (!isNaN(val)) regByPos[pos] = val;
}

const items = $input.all();
const result = [];

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const out = {
    ...j,
    RegistrationScore: regByPos[j.SentrixPosition] ?? null,
  };
  if (i === 0) {
    out._debug_text_length = qcText.length;
    out._debug_reg_positions_count = Object.keys(regByPos).length;
    out._debug_first_pos_value = regByPos['R01C01'];
  }
  result.push({ json: out });
}

return result;

return items.map(item => {
  const r = item.json;

  const sentrix_id = r.SentrixBarcode;
  const position = r.SentrixPosition;

  return {
    json: {
      sentrix_id,
      position,
      sample_id: r.SampleId,
      sample_name: r.SampleName,

      dataset_label: r.DatasetLabel,

      row: r.Row,
      column: r.Column,

      scanner_id: r.ScannerId,
      scanner_version: r.ScannerVersion,
      imaging_date: r.ImagingDate,
      sample_folder_path: r.SampleFolderPath,

      // GTC klasörü sentrix bazlı oluşuyorsa buradan güvenli üretilebilir
      gtc_dir: `/mnt/koza_alldata/Scans/GTCs/${sentrix_id}/gtc`,

      functional_qc_status: r["Functional QC Status"],
      control_qc_flag_codes: r["Control QC Flag Codes"] || null,

      autosomal_call_rate: r.AutosomalCallRate,
      call_rate: r.CallRate,
      log_r_dev: r.LogRDev,
      sex_estimate: r.SexEstimate,

      registration_score: r.RegistrationScore,

      qc_metrics: {
        StainingGreenQC: r.StainingGreenQC,
        StainingRedQC: r.StainingRedQC,
        ExtensionGreenQC: r.ExtensionGreenQC,
        ExtensionRedQC: r.ExtensionRedQC,
        HybridizationHighMediumQC: r.HybridizationHighMediumQC,
        HybridizationMediumLowQC: r.HybridizationMediumLowQC,
        RestorationQC: r.RestorationQC,
        TargetRemovalIQC: r.TargetRemovalIQC,
        StringencyQC: r.StringencyQC,
        NonSpecificBindingGreenQC: r.NonSpecificBindingGreenQC,
        NonSpecificBindingRedQC: r.NonSpecificBindingRedQC,
        NonPolymorphicGreenQC: r.NonPolymorphicGreenQC,
        NonPolymorphicRedQC: r.NonPolymorphicRedQC
      },

      raw_control_metrics: r
    }
  };
});
